function render() {
		if ( ! current_user_can( self::CAP ) ) { wp_die( 'Neturite teisių.' ); }
		global $wpdb;
		$t = $wpdb->prefix . 'ps_pets';

		$real  = (int) $wpdb->get_var( "SELECT COUNT(*) FROM $t WHERE deleted_at IS NULL AND is_test = 0" );
		$test  = (int) $wpdb->get_var( "SELECT COUNT(*) FROM $t WHERE deleted_at IS NULL AND is_test = 1" );
		// Jei realių dar nėra — rodom testinius, bet aiškiai pasakom.
		$show_test = isset( $_GET['test'] ) ? ( $_GET['test'] === '1' ) : ( $real === 0 && $test > 0 );
		$where     = 'deleted_at IS NULL' . ( $show_test ? '' : ' AND is_test = 0' );
		$total     = (int) $wpdb->get_var( "SELECT COUNT(*) FROM $t WHERE $where" );

		echo '<div class="wrap"><h1>Augintinių anketos įžvalgos</h1>';

		if ( $show_test ) {
			echo '<div class="notice notice-warning"><p><strong>Rodomi ir testiniai profiliai.</strong> '
				. 'Realių profilių: <strong>' . $real . '</strong>, testinių: <strong>' . $test . '</strong>. '
				. ( $real > 0 ? '<a href="' . esc_url( admin_url( 'admin.php?page=' . self::SLUG . '&test=0' ) ) . '">Rodyti tik realius</a>' : 'Realių dar nėra.' )
				. '</p></div>';
		} elseif ( $test > 0 ) {
			echo '<p style="color:#666">Testiniai profiliai (' . $test . ') neįtraukti. '
				. '<a href="' . esc_url( admin_url( 'admin.php?page=' . self::SLUG . '&test=1' ) ) . '">Įtraukti juos</a></p>';
		}

		if ( ! $total ) {
			echo '<div class="notice notice-info"><p>Profilių dar nėra.</p></div></div>';
			return;
		}

		self::css();
		echo '<div class="ps-ins-grid">';

		// --- Apimtis ---
		$w_weight = (int) $wpdb->get_var( "SELECT COUNT(*) FROM $t WHERE $where AND current_weight_kg IS NOT NULL" );
		$w_food   = (int) $wpdb->get_var( "SELECT COUNT(*) FROM $t WHERE $where AND (primary_product_id IS NOT NULL OR wet_product_id IS NOT NULL)" );
		$w_sens   = (int) $wpdb->get_var( "SELECT COUNT(*) FROM $t WHERE $where AND sensitivities IS NOT NULL AND sensitivities <> ''" );
		$w_ster   = (int) $wpdb->get_var( "SELECT COUNT(*) FROM $t WHERE $where AND is_sterilised = 'yes'" );
		self::card( 'Apimtis', array(
			array( 'Profilių', $total, null ),
			array( 'Nurodytas svoris', $w_weight, $total ),
			array( 'Priskirtas maistas', $w_food, $total ),
			array( 'Nurodyti jautrumai', $w_sens, $total ),
			array( 'Sterilizuoti', $w_ster, $total ),
		) );

		// --- Rūšys ---
		self::group_card( 'Rūšys', $wpdb->get_results(
			"SELECT species AS v, COUNT(*) AS c FROM $t WHERE $where GROUP BY species ORDER BY c DESC", ARRAY_A
		), 'species', $total );

		// --- Maitinimo būdas ---
		self::group_card( 'Kuo maitina', $wpdb->get_results(
			"SELECT IFNULL(feeding_type,'') AS v, COUNT(*) AS c FROM $t WHERE $where GROUP BY feeding_type ORDER BY c DESC", ARRAY_A
		), 'feeding', $total );

		// --- Poreikiai (asortimento signalas) ---
		self::group_card( 'Kas aktualiausia', $wpdb->get_results(
			"SELECT IFNULL(primary_need,'') AS v, COUNT(*) AS c FROM $t WHERE $where GROUP BY primary_need ORDER BY c DESC", ARRAY_A
		), 'need', $total );

		// --- Jautrumai: CSV isskaidom ---
		$rows = $wpdb->get_col( "SELECT sensitivities FROM $t WHERE $where AND sensitivities IS NOT NULL AND sensitivities <> ''" );
		$sens = array();
		foreach ( $rows as $csv ) {
			foreach ( explode( ',', (string) $csv ) as $code ) {
				$code = trim( $code );
				if ( $code === '' ) { continue; }
				if ( ! isset( $sens[ $code ] ) ) { $sens[ $code ] = 0; }
				$sens[ $code ]++;
			}
		}
		arsort( $sens );
		$sens_rows = array();
		foreach ( $sens as $k => $v ) { $sens_rows[] = array( 'v' => $k, 'c' => $v ); }
		self::group_card( 'Jautrumai', $sens_rows, 'sens', $total,
			'Vienas augintinis gali turėti kelis — todėl suma gali viršyti profilių skaičių.' );

		echo '</div>';

		// --- Laisvi „Kita" tekstai: ko zmones prasi, o mes nesiulom ---
		$other = $wpdb->get_col( "SELECT DISTINCT primary_need_other FROM $t WHERE $where AND primary_need_other IS NOT NULL AND primary_need_other <> ''" );
		$other_ft = $wpdb->get_col( "SELECT DISTINCT feeding_type_other FROM $t WHERE $where AND feeding_type_other IS NOT NULL AND feeding_type_other <> ''" );
		if ( $other || $other_ft ) {
			echo '<h2 style="margin-top:26px">„Kita" — ką žmonės įrašė patys</h2>';
			echo '<p style="color:#666;margin-top:-6px">Tai, kam sąraše vietos neatsirado. Vertingiausia asortimento signalų dalis.</p>';
			echo '<table class="widefat striped" style="max-width:760px"><thead><tr><th>Kontekstas</th><th>Tekstas</th></tr></thead><tbody>';
			foreach ( $other as $x )    { echo '<tr><td>Aktualiausia</td><td>' . esc_html( $x ) . '</td></tr>'; }
			foreach ( $other_ft as $x ) { echo '<tr><td>Maitinimo būdas</td><td>' . esc_html( $x ) . '</td></tr>'; }
			echo '</tbody></table>';
		}

		// --- Pirkimai is plano ---
		if ( class_exists( 'Petshop_Plan_Attribution' ) ) {
			$days = isset( $_GET['days'] ) ? max( 0, (int) $_GET['days'] ) : 30;
			$st   = Petshop_Plan_Attribution::stats( $days ?: null );
			if ( $st ) {
				echo '<h2 style="margin-top:26px">Pirkimai iš Mitybos plano</h2>';
				echo '<p style="color:#666;margin-top:-6px">Rodo, kiek pirkimų įvyko <strong>per planą</strong>. '
					. 'Tai priskyrimas, ne priežastingumas — dalis šių prekių būtų nupirkta ir be plano.</p>';
				$sel = function( $d, $lbl ) use ( $days ) {
					$u = admin_url( 'admin.php?page=' . self::SLUG . '&days=' . $d );
					return ( (int) $days === (int) $d )
						? '<strong>' . $lbl . '</strong>'
						: '<a href="' . esc_url( $u ) . '">' . $lbl . '</a>';
				};
				echo '<p>' . $sel(7,'7 d.') . ' &nbsp;·&nbsp; ' . $sel(30,'30 d.') . ' &nbsp;·&nbsp; ' . $sel(0,'Viskas') . '</p>';
				$adds = (int) $st['adds'];
				$conv = (int) $st['converted'];
				$rate = $adds > 0 ? round( 100 * $conv / $adds ) : 0;
				echo '<div class="ps-ins-grid" style="max-width:760px">';
				self::card( 'Krepšelis ir užsakymai', array(
					array( 'Įdėta į krepšelį (eilučių)', $adds, null ),
					array( 'Iš jų pateko į užsakymą', $conv, $adds ?: null ),
					array( 'Užsakymų su plano prekėmis', (int) $st['orders'], null ),
				) );
				echo '<div class="ps-ins-card"><h2>Vertė</h2><table>'
					. '<tr><td>Įdėta į krepšelį</td><td class="ps-ins-num">' . wc_price( (float) $st['add_value'] ) . '</td></tr>'
					. '<tr><td>Pateko į užsakymą</td><td class="ps-ins-num">' . wc_price( (float) $st['conv_value'] ) . '</td></tr>'
					. '<tr><td>Konversija</td><td class="ps-ins-num">' . $rate . '%</td></tr>'
					. '</table><p class="ps-ins-note">Vertė skaičiuojama pagal kainą įdėjimo metu.</p></div>';
				echo '</div>';
				if ( ! empty( $st['by_source'] ) ) {
					echo '<table class="widefat striped" style="max-width:520px;margin-top:12px">'
						. '<thead><tr><th>Iš kur</th><th>Įdėta</th><th>Užsakyta</th></tr></thead><tbody>';
					$lbl = array( 'plan_dry' => 'Sausas maistas', 'plan_wet' => 'Konservai' );
					foreach ( $st['by_source'] as $r ) {
						echo '<tr><td>' . esc_html( isset( $lbl[ $r['source'] ] ) ? $lbl[ $r['source'] ] : $r['source'] ) . '</td>'
							. '<td>' . (int) $r['adds'] . '</td><td>' . (int) $r['converted'] . '</td></tr>';
					}
					echo '</tbody></table>';
				}
			}
		}

		// --- Dazniausiai priskirti produktai ---
		$top = $wpdb->get_results(
			"SELECT primary_product_id AS pid, COUNT(*) AS c FROM $t
			 WHERE $where AND primary_product_id IS NOT NULL
			 GROUP BY primary_product_id ORDER BY c DESC LIMIT 15", ARRAY_A );
		if ( $top ) {
			echo '<h2 style="margin-top:26px">Dažniausiai priskirtas sausas maistas</h2>';
			echo '<table class="widefat striped" style="max-width:760px"><thead><tr><th>Produktas</th><th style="width:90px">Profilių</th></tr></thead><tbody>';
			foreach ( $top as $r ) {
				$p = function_exists( 'wc_get_product' ) ? wc_get_product( (int) $r['pid'] ) : null;
				$nm = $p ? $p->get_name() : ( '#' . (int) $r['pid'] . ' (nebėra)' );
				$lnk = $p ? '<a href="' . esc_url( get_edit_post_link( (int) $r['pid'] ) ) . '">' . esc_html( $nm ) . '</a>' : esc_html( $nm );
				echo '<tr><td>' . $lnk . '</td><td>' . (int) $r['c'] . '</td></tr>';
			}
			echo '</tbody></table>';
		}

		echo '</div>';
	}

	/** Kortele su „X is Y" eilutemis. */
	private static function card( $title, $rows ) {
		echo '<div class="ps-ins-card"><h2>' . esc_html( $title ) . '</h2><table>';
		foreach ( $rows as $r ) {
			$pct = ( $r[2] && $r[2] > 0 ) ? ' <span class="ps-ins-pct">' . round( 100 * $r[1] / $r[2] ) . '%</span>' : '';
			echo '<tr><td>' . esc_html( $r[0] ) . '</td><td class="ps-ins-num">' . (int) $r[1] . $pct . '</td></tr>';
		}
		echo '</table></div>';
	}

